from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    x,y=q.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==color:
                            seen.add((a,b)); q.append((a,b))
                comps.append((color,comp))
    comps.sort(key=lambda z:max(c for r,c in z[1]), reverse=True)
    out=[[0]*w for _ in range(h)]
    for color,comp in comps:
        occupied={(r,c) for r in range(h) for c in range(w) if out[r][c]}
        # Remaining unprocessed objects are not in out yet; we need distinguish, but placed components maintained.
        # Current and remaining input cells handled by per-component movement collision against out only.
        shift=0
        while all(c+shift+1<w and (r,c+shift+1) not in occupied for r,c in comp):
            shift+=1
        for r,c in comp:
            out[r][c+shift]=color
    return out

